const CURRENT_TERMS_VERSION="2.0",TERMS_API="https://api.buildskil.com/api/terms",termsModal=document.getElementById("termsModal"),termsCheckbox=document.getElementById("termsCheckbox"),termsError=document.getElementById("termsError"),termsCloseBtn=document.getElementById("termsCloseBtn");function getToken(){return localStorage.getItem("cb_token")}async function getTermsStatus(){const e=getToken();if(!e)throw new Error("Please sign in again.");const n=await fetch(`${TERMS_API}/status`,{method:"GET",headers:{Accept:"application/json",Authorization:`Bearer ${e}`}}),t=await n.json();if(!n.ok)throw new Error(t?.message||"Could not check terms status.");return t}async function acceptTermsFromBackend(){const e=getToken();if(!e)throw new Error("Please sign in again.");const n=await fetch(`${TERMS_API}/accept`,{method:"PATCH",headers:{Accept:"application/json","Content-Type":"application/json",Authorization:`Bearer ${e}`},body:JSON.stringify({termsVersion:"2.0"})}),t=await n.json();if(!n.ok)throw new Error(t?.message||"Could not save terms acceptance.");if(t?.data?.termsAccepted!==!0)throw new Error("Terms acceptance was not saved.");return t}function showTermsModal(){termsModal&&(termsModal.hidden=!1,document.body.style.overflow="hidden",termsCheckbox&&(termsCheckbox.checked=!1,termsCheckbox.disabled=!1),termsError&&(termsError.hidden=!0))}function closeTermsModal(){termsModal&&(termsModal.hidden=!0,document.body.style.overflow="")}async function checkTermsVersion(){try{const e=await getTermsStatus(),n=e?.data?.termsAccepted===!0,t=String(e?.data?.termsVersion||"").trim();!n||t!=="2.0"?showTermsModal():closeTermsModal()}catch(e){console.error("Terms status error:",e),showTermsModal()}}function setupTermsCheckbox(){termsCheckbox&&termsCheckbox.addEventListener("change",async function(){if(!this.checked){termsError&&(termsError.hidden=!1);return}termsError&&(termsError.hidden=!0);try{this.disabled=!0,await acceptTermsFromBackend(),closeTermsModal()}catch(e){console.error("Terms acceptance error:",e),this.checked=!1,termsError&&(termsError.textContent=e.message||"Could not save your acceptance.",termsError.hidden=!1)}finally{this.disabled=!1}})}function setupTermsModal(){termsModal&&termsModal.addEventListener("click",function(e){e.target===termsModal&&e.stopPropagation()})}document.addEventListener("DOMContentLoaded",async function(){setupTermsCheckbox(),setupTermsModal(),await checkTermsVersion()});function closeTermsModalWithCheck(){if(!termsCheckbox?.checked){termsError?.removeAttribute("hidden"),termsCheckbox?.focus();return}termsError?.setAttribute("hidden",""),termsModal?.setAttribute("hidden",""),document.body.style.overflow=""}termsCloseBtn?.addEventListener("click",closeTermsModalWithCheck);
